<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\UploadContent;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Connector\FileStorage\BinaryContent;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility\SnippetAssetVisibilityService;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetUploadContentUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetAssetVisibilityService $visibility,
        private readonly SnippetAssetWriteGateway $writer
    ) {
    }

    public function allowUpload(): Allow
    {
        $this->logDebug("Check allow of temp upload Content usecase for Snippet asset");
        $span = $this->startSpan("Check allow of temp upload Content usecase for Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetUploadContentAllowDecision(Allow::allowed('upload', 'Allowed to upload by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function readTemporal(string $query): BinaryContent
    {
        $this->logDebug("Run retrieve temp upload Content usecase for Snippet asset");
        $span = $this->startSpan("Run retrieve temp upload Content usecase for Snippet asset");
        try {
            $allow = $this->allowUpload();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to read tempora upload for Snippet asset');
            }
            return $this->writer->readTemporalContent($query);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function temporalStore(BinaryContent $binary): string
    {
        $this->logDebug("Run temp upload Content usecase for Snippet asset");
        $span = $this->startSpan("Run temp upload Content usecase for Snippet asset");
        try {
            $allow = $this->allowUpload();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to upload store on Snippet asset');
            }
            $this->dispatcher->dispatch(new SnippetAssetUploadContentCheck($binary));
            $input = $this->dispatcher->dispatch(new SnippetAssetUploadContentEnrich($binary, $binary));
            return $this->writer->temporalStoreContent($input->getResult());
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
